insert into public.policies (sort_order, id, title, organization, category, support_type, min_age, max_age, age_text, eligible_regions, min_farming_years, max_farming_years, eligible_farmer_types, requires_business_registration, application_start, application_end, reg, description, details, details_more, eligibility_details, required_documents, official_notice_url, application_url, source_name, last_verified_at, reference_links) values
  (0, 'mafra-young-farmer-settlement', '청년농업인 영농정착지원사업', '농림축산식품부 · 제주시·서귀포시 접수', array['초기자금', '농지']::text[], array['보조금', '융자']::text[], 18, null, '만 18세 이상~만 40세 미만(1985~2008년도 출생자)', '{}'::text[], null, 3, array['예비농', '신규농']::text[], null, '2026-06-01', '2026-07-10', '2026-06-01', null, array['농림축산식품부(장관 송미령, 이하 농식품부)는 ｢2026년 청년농업인 영농정착지원사업｣ 대상자 선발을 위한 1차 모집을 11월 5일(수)부터 개시했다.', '이번 1차 모집에서는 2,000명을 우선 선발하고, 하반기 중 2차 모집을 통해 예산 범위 내에서 잔여 인원을 추가 선발할 예정이다.', '선발된 청년농업인에게는 최장 3년간 월 최대 110만 원의 영농정착지원금과 함께 농지·시설 매입 및 임차를 위한 후계농자금, 농신보 우대보증, 농지 임대 우선지원 등 다양한 연계 지원이 제공된다.', '다만, 후계농자금은 별도의 자금 배정 절차를 거쳐야 하며, 최종 지원 금액은 개인 신용 평가 등 대출 취급기관의 심사 결과에 따라 달라질 수 있으므로 사전 상담을 권장한다.', '또한 양에서 질 중심의 청년농업인 육성을 위해 선정된 청년농들을 대상으로 지자체·품목 조합 중심의 사전 교육도 실시할 계획이다.', '2026년 청년농업인 영농정착지원사업에 지원하려는 청년은 2025년 12월 11일까지 농림사업정보시스템(uni.agrix.go.kr)을 통해 신청하면 된다.', '사업 지침과 관련 정보는 ‘탄탄대로’(youngfarmer.greendaero.go.kr)에서 확인할 수 있으며, 궁금한 사항은 청년농업인 안내 콜센터(1670-0255)로 문의하면 된다.', '사업대상자는 12월 진행되는 서류 평가와 면접 평가를 거쳐 2026년 1월 중 최종 확정된다.']::text[], null, array['만 18세 이상~만 40세 미만(1985~2008년도 출생자)의 독립 영농경력 3년 이하인 청년농업인 또는 예정자 중, 소득과 재산이 일정 수준* 이하인 경우 신청할 수 있다.', '* 본인세대의 건강보험료 산정액(본인부담액 또는 부과액) 기준으로 기준중위소득 140% 초과한 경우 신청 불가']::text[], '{}'::text[], 'https://www.mafra.go.kr/home/5109/subview.do?enc=Zm5jdDF8QEB8JTJGYmJzJTJGaG9tZSUyRjc5MiUyRjU3NTgxMCUyRmFydGNsVmlldy5kbyUzRg%3D%3D', 'https://www.nongupez.go.kr', '농림축산식품부 보도자료, 제주시 공고(보도)', '2026-11-15', '[{"label":"탄탄대로: 청년농 사업 안내","url":"https://youngfarmer.greendaero.go.kr"},{"label":"정책브리핑: 2026년 모집 개시 보도자료","url":"https://www.korea.kr/briefing/pressReleaseView.do?newsId=156724963"},{"label":"정부24 정책뉴스: 2025년 모집 안내 (지난 공고)","url":"https://www.gov.kr/portal/gvrnPolicy/view/H2412000001130412?policyType=G00301&Mcode=11218"},{"label":"정부24: 2025년 모집 공고 (지난 공고)","url":"https://www.gov.kr/portal/locgovNews/4123347"},{"label":"뉴스N제주: 제주시 2026년 2차 모집","url":"https://www.newsnjeju.com/news/articleView.html?idxno=285751"},{"label":"제주청년플랫폼: 2025 제주시 청년창업농 영농정착 지원 (지난 안내)","url":"https://jejuyouthdream.com/support-policy/9"},{"label":"제주도민일보: 제주시 2026년 영농정착지원사업 2차 선발 모집 (시정뉴스)","url":"https://www.jejudomin.co.kr/news/articleView.html?idxno=319714"}]'::jsonb),
  (1, 'jeju-si-youth-farmland-rent-2026-h2', '제주시 청년농업인 농지 임대료 지원 (2026년 하반기)', '제주시 친환경농정과', array['농지']::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, array['기존 농업경영체']::text[], null, null, '2026-11-10', '2026-10-16', null, '{}'::text[], null, '{}'::text[], '{}'::text[], null, null, '제주시 발표 (헤드라인제주 보도)', '2026-11-15', '[{"label":"헤드라인제주: 제주, 청년농업인 농지 임대료 지원","url":"https://www.headlinejeju.co.kr/news/articleView.html?idxno=600562"},{"label":"제주의소리: 제주시 청년농업인 농지 임대료 지원 신청 접수","url":"https://www.jejusori.net/news/articleView.html?idxno=507453"},{"label":"제주투데이: 제주시, 청년농업인 농지 임대료 지원","url":"https://www.ijejutoday.com/news/articleView.html?idxno=403417"}]'::jsonb),
  (2, 'seogwipo-youth-loan-interest-2026', '서귀포시 청년농업인 정책자금 이자보전 지원 (2026)', '서귀포시', array['초기자금']::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, array['기존 농업경영체']::text[], null, '2026-10-29', '2026-11-13', '2026-10-29', null, '{}'::text[], null, '{}'::text[], '{}'::text[], null, null, '서귀포시 발표 (언론 보도)', '2026-11-15', '[{"label":"헤드라인제주: 서귀포시, 청년농업인 정책자금 이자보전 지원사업 신청 접수","url":"https://www.headlinejeju.co.kr/news/articleView.html?idxno=601555"},{"label":"제주매일: 청년농업인 정책자금 이자보전 지원","url":"https://www.jejumaeil.net/news/articleView.html?idxno=406338"},{"label":"뉴스N제주: 청년농업인 정책자금 이자보전 지원 신청","url":"https://www.newsnjeju.com/news/articleView.html?idxno=303708"}]'::jsonb),
  (3, 'jeju-youth-farmer-incubating-2026', '청년농업인 창업 인큐베이팅 지원사업 (2026)', '제주특별자치도', array['초기자금']::text[], array['보조금', '컨설팅']::text[], 19, 45, null, array['제주특별자치도 전체']::text[], null, null, array['예비농', '신규농']::text[], null, '2026-02-24', '2026-03-17', '2026-02-24', '- 청년농업인 초기 영농 및 창업 비용 지원으로 농업분야 성공적 진출 및 정착 유도를 통한 제주 농촌을 주도할 청년 인적자원 확보', array['사업기간: 2026. 2~12월', '사 업 량: 청년농업인 10명 내외', '사 업 비: 75,600천원(자체재원)', '지원한도: 농가당 7,560천원 범위 내', '지원내용: 시제품 제작, 기계·장비 임차료, 컨설팅 비용, 교육비 등 청년농업인의 초기 영농창업비 지원', '신청기간 2026-02-24 ~ 2026-03-17', '신청방법: 방문신청', '신청장소: 제주도청 친환경농업정책과 강다희 주무관', '- 주소: 제주시 문연로 6, 제주도청 1청사 별관 2층 친환경농업정책과', '문의처 064-710-3054']::text[], null, array['지원대상: 3년 이상 제주도에 주소를 두고 거주하면서 신규 또는 부모의 농업을 승계하여 농업에 종사하는 19세 이상 45세 이하(1981.1.1.~2007.12.31. 출생자)인 청년농업인']::text[], array['사업신청서', '사업계획서', '주민등록본(초본)', '농업경영체 등록 확인서', '지방세납세증명서', '건강보험자격득실확인서 등']::text[], 'https://jejuyouthdream.com/policy/detail/74', null, '제주청년플랫폼 청년이어드림', '2026-11-15', '[]'::jsonb),
  (4, 'jeju-small-farm-support-2026', '소규모 농가·청년농 농기자재비 지원 (2026)', '제주특별자치도 · 제주시', array['초기자금']::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-02-03', '2026-02-23', '2026-02-03', '소규모 농가 중심의 영농자재 지원을 통한 농가경영 안정 및 지속가능한 영농환경 조성', array['사업기간 2026-02-01 ~ 2026-12-31', '신청기간 2026-02-03 ~ 2026-02-23', '영농활동에 필요한 농기자재* 구입비 농가당 최대 150천원 지원', '* 비료, 농약, 종자, 농업용 보조(안전)용품, 500천원 이하 소모성 농기구 구입 가능', '※ 단, 농·감협에서 구입한 품목에 한하며 농기계등 시설장비(500천원 초과), 부과세 환급 품목, 면세유는 대상품목 제외', '신청방법- 주소지 읍·면 사무소 및 동 주민센터', '문의처 064-710-3026', '※ 지원규모: 별도 기준에 따라 심사']::text[], null, array['※ 지원순위에 따라 지원예정임', '(1순위) 품목별 자조금 가입 청년농업인', '(2순위) 품목별 자조금 가입 0.5ha 이하의 소규모 농가 경영주', '(3순위) 1,2순위에 해당하지 않는 청년농 및 소규모 농가 경영주', '※ ① 자조금 미가입 품목 청년농 → ② 자조금이 없는 품목 0.5ha 이하 소규모 농가 재배 농가 순으로 결정', '(4순위) 본 보조사업을 지원받은 이력(`23~`25)이 있는 농가']::text[], '{}'::text[], 'https://jejuyouthdream.com/policy/detail/73', null, '제주청년플랫폼 청년이어드림, 제주시 공고(보도)', '2026-11-15', '[{"label":"제주도민일보: 2026년 소규모 농가 경영안정 지원사업 (제주시 공고)","url":"https://www.jejudomin.co.kr/news/articleView.html?idxno=316963"}]'::jsonb),
  (5, 'krc-farmland-bank-young-farmer', '농지은행 청년농 농지 지원 (선임대후매도·공공임대)', '한국농어촌공사', array['농지']::text[], array['융자', '임대']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, null, null, '2026-07-29', null, array['지원내용 : 농지은행이 농지를 매입, 임차하여 청년농 등에게 매도, 임대 지원', '① 농지매매', '지원단가 : (생애첫/청년농) 38,500원/㎡', '융자상환 : 11~30년간 원금분할상환, 연리 1%', '② 공공임대', '임대기간 : 5년 단위(평가를 통해 연장 가능)', '임차료 : 표준임차료(해당지역 관행임차료 평균 수준)의 50~100%범위 내에서 공사와 합의하여 결정', '③ 임차임대', '임대기간 : 5년 이상 10년 이하', '임차료 : 공사에서 당해 농지에 대해 조사한 임대차료 수준과 임대차료 동향 등을 고려, 임차인과 협의하여 현금으로 환산 결정', '초기 자본이 부족한 청년농을 돕기 위해 매매는 0.5ha, 임대는 1.0ha까지 추가로 지원된다.', '청창농 외 : 진입 1.5㏊ / 성장 2.5㏊', '생애첫: 진입 1.0㏊ / 성장 1.5㏊', '* 생애첫: 농지 취득 이력이 없는 청년농']::text[], null, array['지원대상 : 청년후계농(우선순위), 2030세대, 후계농, 귀농인, 일반농']::text[], '{}'::text[], 'https://www.ekr.or.kr/Kkrpub/webzine/2026/01+02/community.html', null, '한국농어촌공사, 언론 보도', '2026-11-15', '[{"label":"천지일보: 청년농 농지 임대료 80% 감면, 농지은행 개편","url":"https://www.newscj.com/news/articleView.html?idxno=3421019"},{"label":"라이브뉴스: 농어촌공사, 농지은행 개편","url":"https://www.livesnews.com/news/article.html?no=63022"}]'::jsonb),
  (6, 'jeju-si-successor-farmer-loan-2026', '후계농업경영인 육성 지원사업 (제주시, 2026)', '제주시', array['초기자금', '농지']::text[], array['융자']::text[], 18, 49, null, '{}'::text[], null, null, array['예비농', '신규농']::text[], null, null, '2026-02-11', '', null, array['ㅇ 대출 실행기간 : 사업 선정연도 기준 5년 이내(`30년 12월 말까지)', 'ㅇ 대출한도 : 세대당* 최대 5억원**', '* 주민등록상 세대주·세대원을 포함하며, 가족관계증명서상 부부는 한 세대로 간주', '** 정책자금 지원 규모는 사업대상자의 담보가치 및 신용상태 등에 대한 대출취급 기관의 평가에 따라 최종 결정', 'ㅇ 대출금리 : 연 1.5%(고정금리)', 'ㅇ 대출(상환)기간 : 5년 거치 20년 원금 균등분할 상환', 'ㅇ 실제 대출금액은 신청자의 담보가치 및 신용상태 등에 대한 대출취급기관의 평가에 따라 결정', 'ㅇ 정부 귀농자금을 지원받은 금액은 대출한도에서 차감']::text[], null, array['1) 다음 각 호의 요건에 모두 해당해야 신청 가능', '가. 연령 : 사업 시행연도 기준 18세～49세(1976~2008년도 출생자)', '나. 영농경력: 영농에 종사한 경력이 없거나 10년 미만', '다. 병역 : ''26 산업기능요원 편입대상자가 아닌 미필자는 군 복무 완료 후 후계농업경영인 육성자금 대출 배정·신청 가능', '라. 거주지: 사업 신청하는 시·군·특광역시에 실제 거주(주민등록 포함)', '마. 교육실적 : 대학의 농업 관련 학과나 농업계 고등학교를 졸업하였거나 시장·군수·구청장이 인정한 농업 교육기관에서 관련 교육을 이수한 자(미해당자 신청 불가)', '2) 1)의 요건을 갖춰도 다음 각호의 요건에 해당하면 사업 신청 불가', '가. 본인 명의 사업자 등록(개인·법인) 및 법인 설립 등기를 한 자', '나. 공공기관 및 회사 등에 상근 직원으로 채용되어 매월 보수 또는 보수에 준하는 급여를 받고 있는 자', '다. 고등학교·대학교 재학생과 휴학생', '라. 임업후계자 지원 대상 품목을 재배하려는 자', '마. 진돗개를 제외한 개의 사육을 하는 자', '바. 후계농업경영인으로 선정된 적이 있거나 자금 지원을 받은 자', '사. 「농림축산식품분야 재정사업관리 기본규정」 제79조에 따라 부정수급에 해당하여 처분을 받고 있는 자']::text[], '{}'::text[], null, 'https://www.nongupez.go.kr', '제주시 공고(제주도민일보 게재), 농림축산식품부 시행지침', '2026-11-15', '[{"label":"제주도민일보: 2026년 후계농업경영인 지원사업 대상자 모집","url":"https://www.jejudomin.co.kr/news/articleView.html?idxno=316507"},{"label":"농림축산식품부: 2026년 후계농업경영인 육성사업 시행지침","url":"https://mafra.go.kr/bbs/home/791/593059/download.do"}]'::jsonb),
  (7, 'jeju-dongbu-young-farmer-studygroup-2026', '청년농업인 영농문제해결 스터디그룹 (동부농업기술센터)', '제주특별자치도 동부농업기술센터', array['영농기술', '판로', '네트워크(지역사회 관계)']::text[], array['교육', '컨설팅']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-04-06', '2026-06-30', '2026-04-06', '스터디그룹 운영으로 영농문제 해결 및 농촌자원 활용 새 소득 사업 발굴을 통한 청년농업인 경쟁력 강화', array['운영기간: 2026년 4월 ~ 11월', '운영횟수: 그룹당 15회 내외 * 월별 1~2회 내외(회당 최대 4시간 이내)로 자율적 운영', '운영장소: 그룹별 자율 선정', '운영분야: 센터별 지역특화작목 및 농촌융복합산업 등', '모집인원: 동부농업기술센터 1팀(팀별 5~10명) *조기모집 시 마감될 수 있음', '※ 기존 그룹(분야: 여성농업인 6명) 지속 운영, 개인용, 그룹용 참여신청서ㆍ서약서 제출', '- 영농문제 해결 및 농촌자원 활용 새 소득 사업 발굴을 위한 스터디그룹 활동지원(현장교육, 현장실습, 강사초빙 등)', '- 청년농업인 영농기술 습득 및 사업발굴을 통한 농가 소득화 모색', '(필수) (개인용, 그룹용)스터디그룹 참여 신청서, 책임 서약서 제출', '스터디그룹 인원: 팀당 5~10명 이내', '스터디그룹 운영: 월별 1~2회 이내, 최대 총 15회 이내 * 참석인원 80% 이상', '스터디그룹 운영 활동 지원(영농문제 해결, 사업 발굴 등)', '그룹별 결과 평가회 개최: 12월', '신청기간: 2026. 4. 6.(월) ~ 6. 30.(화) * 상반기 내 수시모집', '신청기관: 기술지원조정과 및 4개 농업기술센터', '신청방법: 분야별 각 센터 방문접수', '월ㆍ반기별 운영결과 제출 *별도 서식 제공', '청년농업인 스터디그룹 운영 과정을 수료한 청년농업인에게 교육 시간 인정 (최대 60시간(15회 내외*4시간) 인정)', '- 전체 교육시간의 80% 이상 참석: 수료', '- 전체 교육시간의 30% 이상 참석: 이수, 실 참석시간만큼 인정', '- 전체 교육시간의 30% 미만 참석: 미수료, 교육시간 불인정']::text[], null, array['신청대상: 도내 청년농업인, 4-H회원 및 후계농업경영인', '* 청년농업인: 3년이상 제주특별자치도에 주소를 두고 거주하면서 신규 또는 부모의 농업을 승계하여 영농에 종사하는 19세 이상 45세 이하 청년농업인 (1981. 1. 1. ~ 2007. 12. 31. 출생자)']::text[], array['[붙임1] (개인용)스터디그룹 참여 신청서', '[붙임2] (개인용)교육참여 책임 서약서', '[붙임3] (그룹용)스터디그룹 참여 신청서']::text[], 'https://agri.jeju.go.kr/dongbu/notice/notice.htm?act=view&seq=59748', null, '제주특별자치도 농업기술원 동부농업기술센터', '2026-11-15', '[{"label":"뉴스서울: 제주도, 청년농업인 성장 지원 본격화","url":"https://newsseoul.co.kr/news/view/1065609061867047"}]'::jsonb),
  (8, 'jeju-seogwipo-rural-convergence-edu-2026', '농촌융복합산업 실무역량 강화 교육 (서귀포농업기술센터)', '제주특별자치도 서귀포농업기술센터', array['영농기술', '판로']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-10-16', null, '2026-10-07', null, array['교육기간: 2026년 11월 3일(화) ~ 11월 12일(목) 14:00~18:00 / 4회 16시간', '모집인원: 30명', '교육강사: 식품환경연구센터 나혜진 대표, 한국강사교육협회 이지휴 이사, 일로와 이금재 대표, 김도희 치유농업사, 제제포토 오종욱 대표 등 외부강사 초빙', '- 공통사항: 탄소중립, 화학비료 저감사용, 농작업안전 등 홍보영상 시청', '- 식품 제조·가공·체험·판매를 실제로 운영할 때 농업인이 알아야 할 관련 기준과 사례, 고객과의 의사소통 능력과 변화하는 서비스 트렌드 이해, 제주 로컬브랜드의 상품과 공간, 스토리, 플랫폼을 연계한 토탈 마케팅 전략, 치유농업의 이해, 자신의 농산물을 마케팅에 적합한 사진 촬영 실습', '신청기간: 2026년 10월 16일 (금) 9시 ~ 교육인원 모집 완료시까지 (선착순)', '신청방법: 서귀포농업기술센터 누리집 선착순 접수(온라인 신청만 받음)', '* 누리집: https://agri.jeju.go.kr/seogwipo/index.htm', '문의처: 서귀포농업기술센터 농촌자원팀 (☎760-7831~2)', '농업인 교육 운영관리 지침에 의거 수료생 관리', '- 교육과정(횟수 또는 시간) 80% 이상 이수한 경우 전체 교육시간 인정, 30% 이상 이수한 경우 이수시간 만큼 교육시간 인정', '교육 과정 종료 시 교육생 설문조사를 통한 교육운영 평가 및 개선방향 검토']::text[], null, array['교육대상: 농촌자원 활용 가공·체험·서비스·브랜드가치에 관심 있는 농업인', '모집인원 및 대상: 교육희망 농업인 30명']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=62073', null, '제주특별자치도 서귀포농업기술센터 공지사항', '2026-11-15', '[{"label":"한라일보: 농촌융복합산업 실무역량 강화 교육 수강생 모집","url":"http://www.ihalla.com/article.php?aid=1791854581791495010"}]'::jsonb),
  (9, 'jeju-dongbu-rural-startup-school-2026', '농촌융복합 창업 스쿨 현장 교육 (동부농업기술센터)', '제주특별자치도 동부농업기술센터', array['영농기술', '판로']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-10-01', null, '2026-09-22', '농촌융복합사업에 관심이 있으며 사업 추진을 해 보고 싶은 농업인들이 벤치마킹을 통해 자기 농장의 창업을 간접 경험 할 수 있도록 하여 시행착오를 줄이는 창업 노하우를 배우기 위함.', array['교육기간: 2026년 10월 14일 ~ 10월 28일(매주 수요일) 14:00~18:00 / 3회 12시간', '교육인원: 20명', '교육장소: 동부농업기술센터 농촌생활과학관 및 농장 현지', '교육강사: 선도농업인 등 외부강사 초빙', '- 치유농업의 이해 및 농장별 치유프로그램의 차별화 전략', '→ 감귤농장과 싱잉볼 명상, 백가지 향이 나는 귤, 곤충테마치유', '- 농산물가공 사업 추진시 주의 사항 및 판매전략', '→ 당근체험키트, 지역농산물 이용 가공 실습(당근잼, 메밀빵)', '신청기간: 2026년 10월 01일(목) 9시 ~ 교육인원 모집 완료시까지', '신청방법 : 동부농업기술센터 누리집 선착순 접수(온라인 신청만 받음)', '- [교육신청서] (붙임1) 파일첨부 해야 접수 완료', '* 누리집: https://agri.jeju.go.kr/dongbu/index.htm', '* 온라인신청 방법: https://agri.jeju.go.kr/dongbu/notice/notice.htm?&act=view&seq=62037', '문의처: 동부농업기술센터 농촌자원팀 (☎760-7631~2)', '농업인 교육 운영관리 지침에 의거 수료생 관리', '- 교육과정(횟수 또는 시간) 80% 이상 이수한 경우 전체 교육시간 인정, 30% 이상 이수한 경우 이수시간 만큼 교육시간 인정', '교육 과정 종료 시 교육생 설문조사를 통한 교육운영 평가 및 개선방향 검토']::text[], null, array['교육대상: 농촌융복합사업에 관심이 있는 관내 농업인 (* 경영체등록 확인)', '모집인원: 20명']::text[], '{}'::text[], 'https://agri.jeju.go.kr/dongbu/notice/notice.htm?act=view&seq=62030', null, '제주특별자치도 동부농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (10, 'jeju-agri-tech-pilot-2026', '농업기술보급 시범사업 (제주특별자치도 농업기술원)', '제주특별자치도 농업기술원 기술지원조정과', '{}'::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-09-17', '2026-10-02', '2026-09-18', null, array['2026년 농업기술보급 시범사업 6차 신청 공고입니다.', '- 신청기간: 9월 17일부터 10월 2일 18:00 까지', '- 신청방법: 신청서류 작성 후 해당사업 농업기술센터 방문신청', '담당부서 기술지원조정과 연락처 064-760-7532']::text[], null, '{}'::text[], '{}'::text[], 'https://agri.jeju.go.kr/agri/notice/job/2023.htm?act=view&seq=62002', null, '제주특별자치도 농업기술원 공고', '2026-11-15', '[]'::jsonb),
  (11, 'jeju-seogwipo-farmer-training-plan-2026', '농업인 전문교육 연간 운영계획 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['신규농', '기존 농업경영체']::text[], null, null, null, '2026-02-02', null, array['1. 교육기간: 2026. 1. ~ 12.', '과정별 세부 계획은 별도 수립 후 홈페이지 공고', '교육일정 및 과정은 사정에 의해 변경될 수 있습니다.', '방문접수: 서귀포농업기술센터 농촌자원팀', '새해농업인실용교육: 1과정 1,300명 (☏ 760-7831~3)', '품목별농업인전문교육: 8과정 1,530명 (☏ 760-7831~3)', '신규농업인교육: 3과정 330명 (☏ 760-7831~3)', '농촌자원 활용 교육: 3과정 340명 (☏ 760-7831~3)', '※ 교육일정 및 과정은 사정에 의하여 변경될 수 있으며, 과정별 세부 계획은 별도로 수립 후 공고']::text[], null, array['교육을 희망하는 농업인, 품목농업인연구회원, 농업인단체 등', '신규농업인, 귀농인 및 청년농업인 등', '농촌융복합 사업 관심 소비자 및 사업자 등']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=59355', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[{"label":"농업교육포털 (제주 교육 신청에 쓰인 사례)","url":"https://agriedu.net/"},{"label":"제주청년플랫폼: 2025 귀농귀촌·청년농업인 교육프로그램 (지난 안내)","url":"https://jejuyouthdream.com/support-policy/36"}]'::jsonb),
  (12, 'jeju-seogwipo-new-farmer-course-2026', '신규농업인 전문과정 (서귀포농업기술센터, 종료)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['예비농', '신규농']::text[], null, '2026-09-11', '2026-10-01', '2026-09-07', '신규농업인 전문과정 교육을 통해 배운 영농기술과 다양한 농업정보에 대한 심화 전문 교육을 통해 농업·농촌에 빠른 정착 도모', array['교육기간: 2026. 9. 28.(월) ~ 10. 1.(목) / 3회 12시간', '교육장소: 서귀포농업기술센터 농업인교육관', '※ 상기 일정 및 내용은 사정에 의해 조정될 수 있음.', '접수기간: 2026. 9. 11.(금) ~ 모집인원(40명) 충족시까지', '- 전화접수: ☎ 760-7831, 7832, 7834', '- 방문접수: 서귀포농업기술센터 농촌자원팀', '※ 추가인원은 교육당일 현장 접수', '「농업인 교육 운영관리」지침에 의거하여 교육생 관리', '- 전체 교육시간의 80% 이상 참석: 수료', '- 전체 교육시간의 30% 이상 참석: 이수, 실 참석시간 만큼 인정', '- 전체 교육시간의 30% 미만 참석: 미수료, 교육시간 불인정']::text[], null, array['교육대상: 신규농업인 및 교육희망자 40명 내외', '※ 신규농업인대상 40명내외 모집, 일반 교육희망자는 교육당일 현장에서 추가 접수']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=61950', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (13, 'jeju-agri-meister-college-2027', '제주농업마이스터대학 신입생(10기) 모집 (2027학년도)', '제주특별자치도농업기술원 기술지원조정과 농촌활력팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-11-06', '2026-11-27', '2026-11-09', '최신 농업기술과 경영능력을 갖춘 전문농업경영인(마이스터) 육성을 목표로 운영하는 교육기관 (농림축산식품부 제주특별자치도 지원)', array['도내 농업인으로 영농경력만 갖추면 누구나 지원 가능합니다.']::text[], true, array['◉ 일반전형', '5년(60개월) 이상의 영농경력이 있으며, 신청하는 전공과정의 품목에 대한 중상급 이상의 재배·사육 기술 보유한 농업인', '◉ 특별전형', '3년(36개월) 이상 영농경력이 있고 다음 중 1가지 이상 충족', '① 추천서(시장 또는 기술센터 소장) + 농업교육 100시간 이상 이수 증명서(최근 1년간/온라인 100% 가능)', '② 우수후계농업인', '③ 농업관련 국가기술자격증 취득자', '④ 청년농CEO 과정 수료자(동일 품목에 한함)', '◉ 청년농CEO 과정(감귤분야) :', '만 40세 미만(87년 1월 1일 이후출생)의 청년농업인으로서 농업경영체 등록한 자 또는 농업인 확인서 발급이 가능한자', '◉ 농업마이스터대학 졸업생', '졸업전공 이외의 전공에 지원 가능(단, 신규지원자 우선 선발. 후순위로 미달인 경우 심사를 거쳐 합격여부 결정)']::text[], array['입학원서, <별지서식 1> 참고 - 주민등록등본 등 첨부', '자기학습계획서, <별지서식 2> 참고 - 지원동기 및 목표, 학습희망분야 및 내용, 입학 후 자기주도 학습 계획 등', '농업마이스터대학 교육참여 서약서, <별지서식 3> 참고', '개인정보 수집.이용.제공에 대한 동의서, <별지서식 4> 참고', '전공관련 교육과정 이수증 - 교육이수 확인서 또는 이수증명서 발급 시 반드시 시간 명시 - 단, 온라인 이수증 시수는 서류심사 시 50% 반영', '(일반전형, 특별전형) 입학 신청 전공과정의 품목경력 증빙서류', '○ (경영주) · 농업경영체 등록확인서', '* 농업경영체 미등록한 경우, 구(舊)농지원부의 재배작물 및 영농기간과 현(現)농지대장의 소유사항 또는 임대차사항에 기재된 신청자 성명을 교차 확인하여 품목경력 판단', '○ (경영주 외) · 농업경영체 등록확인서(경영주 외 농업인 기재여부 확인)', '* 농업경영체 미등록한 경우, 구(舊)농지원부의 세대원사항 또는 농지소유 비동거 가족사항, 재배작물 및 영농기간과 농업인 확인서를 교차 확인하여 품목경력 판단', '아래 ①~④ 중 해당되는 서류', '① 추천서(관할 시장/농업기술센터 소장 택1), <별지서식 5> 참고 - 교육이수확인서 또는 교육수료증(최근 1년 100시간 이상)', '② 우수후계농업경영인 확인서', '③ 국가기술자격증, <P. 26> 참고 * 단, 입학 신청 품목전공과 관련된 자격만 인정', '④ 청년농CEO 과정 수료증', '청년농 CEO 과정 마이스터과정 일반전형과 동일', '가산점 (선택) 관련분야 공인자격증 및 표창장 사본 등']::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=62195', null, '제주특별자치도농업기술원 공지사항', '2026-11-15', '[{"label":"서귀포농업기술센터: 2027학년도 제주농업마이스터대학 신입생(10기) 모집","url":"https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=62202"}]'::jsonb),
  (14, 'jeju-agri-youth-ceo-course-2026', '농업 리더 청년농업인CEO 양성과정 (2026)', '제주특별자치도농업기술원 기술지원조정과 농촌활력팀', array['영농기술']::text[], array['교육']::text[], 19, 45, null, array['제주특별자치도 전체']::text[], null, null, '{}'::text[], null, '2026-06-16', '2026-06-29', '2026-06-11', '경영 마인드 함양을 통한 건실한 전문 농업인 경영체로 성장 유도', array['교육기간: 2026. 7. 2.(목) ~ 9. 3.(목) / 10회 39시간', '교육장소: 농업기술원 미래농업육성관 창업지원실 및 IT실, 농업현장 등', '교육내용', '․ 제주DA(3): 제주DA 활용법 및 앱 실습', '․ 농업경영(12): 사업계획서 작성, 기획 및 마케팅, 재무 기획', '․ 홍보ㆍ마케팅(16): AI를 활용한 상품 브랜딩 및 홍보 콘텐츠 제작', '․ 창업분야(4): 농산가공 절차, 법령 및 제조 관련 인ㆍ허가', '․ 현장견학(4): 선배 농업인 현장 방문을 통한 정보 습득 및 네트워크 구축', '* 상기 교육 일정 및 내용은 변경될 수 있음', '- 신청기간: 2026. 6. 16.(화) ~ 6. 29.(월) * 교육인원 충족 시 조기마감', '- 신청방법: 방문(공휴일 제외, 근무시간 내) 또는 온라인 접수', '* 농업기술원 홈페이지 → 교육신청 클릭 → 개인정보 작성, 서류 첨부 및 신청', '한국양성평등교육진흥원에서 양성평등열린교육 이러닝 교육 1시간 이상 이수 시 교육시간 추가 1시간 인정(수료증 필수 제출)', '교육의 원활한 진행을 위한 선발된 교육생은 노트북 지참 및 구글 계정 가입', '담당부서 농촌활력 연락처 064-760-7524']::text[], null, array['교육인원: (도내) 청년농업인 20명(선착순 모집)', '* 청년농업인: 3년이상 제주특별자치도에 주소를 두고 거주하면서 신규 또는 부모님의 농업을 숭계하여 농업에 종사하는 19세 이상 45세 이하인 농업인 (1980. 1. 1. ~ 2007. 12. 31. 출생자)', '※ 청년농업인 대상 교육으로 1980. 1. 1.이전 출생자 접수 불가']::text[], array['② 농업경영체 등록확인서']::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=61491', null, '제주특별자치도농업기술원 공지사항', '2026-11-15', '[]'::jsonb),
  (15, 'jeju-agri-youth-rnd-startup-2026', '청년농업인 R&D 기술창업 통합관리 지원사업 (2026)', '제주특별자치도농업기술원 기술지원조정과 농촌활력팀', array['초기자금', '영농기술']::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-08-18', '2026-08-31', '2026-08-05', '제주특별자치도농업기술원에서는 공공연구기관의 농업 R&D 기술성과를 청년농업인의 창업 자원으로 활용하여 연구 성과 기반 기술창업 모델을 육성함으로써 농업‧농촌의 新성장동력 확보 및 청년농업인의 창업지원으로 농산업 일자리 창출 및 농촌지역 청년 유입을 지원하고자“2026년 청년농업인 R&D 기술창업 통합관리 지원사업”을 다음과 같이 공고합니다.', array['사업기간: 2026. 8. ~ 2027. 12.', '사 업 량: 2개소', '총사업비: 446백만원(국비 200백만원, 도비 200백만원, 자부담 46백만원)', '- 개소당 사업비: 223백만원(보조 200백만원, 자부담 23백만원)', '- 사업비 부담비율: 보조 90%, 자부담 10%', '공공연구기관에서 개발된 농업 R&D 기술성과*를 기반으로 기술이전·공동활용을 통한 사업화를 희망하는 청년농업인 단체에 전문컨설팅과 창업 기반 조성을 종합적으로 지원', '* 농촌진흥청·도농업기술원·농업기술센터, 공공기관에서 개발한 농업 기술 전체', '특허기술 : 농림축산식품 기술사업화 종합정보망(www.nati.or.kr) → 특허정보검색', '영농활용기술 : 농사로(www.nongsaro.go.kr) → 영농기술 → 영농활용정보 → 최신영농활용기술', '사업유형 : 신기술, 가공·상품화, 융복합, 체험·치유·관광', '- 신기술: 농업 신기술, 신품종, 스마트·디지털 기술 등을 활용한 기술창업', '- 가공·상품화: 농산물 및 농업자원을 활용한 가공·제조 기반의 제품 개발 및 상품화', '- 융복합: 농업과 타 산업(식품·바이오·ICT·환경·문화 등)을 결합한 융복합 창업', '- 체험·치유·관광: 농업·농촌 자원을 활용한 체험, 치유, 관광 등 서비스 기반 창업', '* 단순 영농 생산 확대를 위한 시설·장비 지원은 지양하고, 기술 적용과 사업화 중심의 창의적 창업 모델 지원', '사업공모: 2026. 8. 5.(수) ~ 8. 31.(월)', '사업신청 접수기간: 2026. 8. 18.(화) ~ 8. 31.(월) 18:00까지', '- 접 수 처: 서귀포시 중산간서로 212 제주특별자치도농업기술원 기술지원조정과 농촌활력팀', '- 문 의 처: 농업기술원 기술지원조정과 농촌활력팀(064-760-7524)', '신청서류 및 현장․면접 심사를 통해 사업대상자 선정', '- 현장심사: 내부담당자 등 2인 이상, 사업장 기반여건 등 실사 확인', '- 서류․면접심사: 관련분야 전문가 5인이상(외부전문가 3명이상) 구성 운영', '※ 신청자 다수 등 필요 시 발표 평가 등 추가 실시', '- 평가방법: 제출서류(계획서), 현장실사, 면접 등에 대한 심사표에 의함', '서류․면접 심사(80점), 현장심사(20점), 가점(10점) - 심사표 별표 1', '심사결과에 의거 우선순위 작성 농업산학협동심의회 심의 후 대상자 확정', '전문컨설팅: 사업계획과 연관된 창업 및 제품개발 컨설팅을 위해 총사업비의 10% 이내 편성하여 집행', '- 사업대상 단체 선정 후 전문 컨설팅을 실시하여 기존 사업계획서 보완', '* 컨설팅 수행은 관련분야 전문가를 보유하고, 창업‧제품개발 관련 컨설팅이 가능한 사업자등록증을 보유한 적격 업체이어야 함.', '* 사업대상자는 컨설팅 후 보고서를 반드시 제출해야 함.', '창업기반조성: 사업비 민간자본보조로 시설 구축, 장비/기계 구입, 운영시스템 구축 등 창업기반 조성에 필요한 예산으로 편성', '* 본 사업은 공공연구기관 R&D 기술성과의 사업화를 목적으로 하므로, 단순 영농 생산 확대 또는 범용적 활용이 가능한 시설·장비는 지원하지 않음.', '※ 사업 신청 적격여부 검토 중 추가 증빙 서류를 요청할 수 있고, 기관 발급 증빙자료는 신청일 기준 3개월 이내만 유효함.', '※ 제출서류는 일체 반환하지 않으며, 선정 후 기재사항이 허위로 드러날 경우 지원 취소']::text[], null, array['농산업 기술 분야로 청년농업인(만18~39세)이 대표를 맡는 5인 이상의 창업(예정) 법인, 청년농업인 품목모임체* 등으로 공공기관 (농촌진흥청·농업기술원·농업기술센터 등) 개발 농업 R&D 기술을 활용하여 제주특별자치도에 창업을 추진하는 단체', '* 품목모임체: 품목농업인연구회 등 법적 근거가 있고 승인된 단체로 청년농업인으로 5인이상 구성', '사업 목적에 부합하는 인력, 시설, 영농 실적 보유 또는 확보 계획이 가능하고 동일·유사 사업으로 중앙부처·지자체 보조금을 중복 수령하지 않은 법인', '* 휴·폐업 중인 법인, 세금 체납 및 보조금 부정수급 이력이 있는 법인은 지원 대상에서 제외', '* 창업예정인 법인의 경우 당해연도에 제주특별자치도에서 창업 완료해야 함.']::text[], array['제출서류: 사업신청서 및 관련서류(서식 참조)', '※ 필수서류 - 사업신청서(서식1), 일반현황(서식2), 사업계획서(서식3), 지방세 납세증명서, 민간보조금시스템 사업이력', '※ 추가서류 - 법인: 사업자등록증, 법인등기부등본(총회 또는 이사회 회의록 포함), 농업경영체등록확인서(법인), 사업상 소재지 토지 ‧ 건축물대장 및 등기부등본', '- 품목모임체: 품목모임체 승인 문서, 품목모임체 정관 및 회원명부, 농업경영체등록확인서(개인), 사업상 소재지 토지 ‧ 건축물대장 및 등기부등본', '- 창업예정법인: 법인 설립등기 신청서류(정관, 주주명부, 신청내역서 등), 농업경영체등록확인서(개인), 사업상 소재지 토지 ‧ 건축물대장 및 등기부등본', '- 가점서류: 농업인상 수상 사본, 농업인단체임원활동경력확인서, 졸업증명서 (농업관련 학교 및 농업마이스터대학)']::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=61815', null, '제주특별자치도농업기술원 공지사항', '2026-11-15', '[{"label":"제주농업기술센터: 2026년 청년농업인 R&D 기술창업 통합관리 지원사업 공고","url":"https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=61824"}]'::jsonb),
  (16, 'smartfarm-youth-incubator-9th-2026', '스마트팜 청년창업 보육센터 9기 교육생 모집 (2026)', '농림축산식품부 · 제주특별자치도농업기술원 안내', array['영농기술']::text[], array['교육']::text[], 18, 39, null, '{}'::text[], null, null, array['예비농', '신규농']::text[], null, '2026-04-30', '2026-05-29', '2026-05-07', '스마트팜 기초 입문(이론)교육 · 교육형 실습 · 경영형 실습 단계별 교육과정 운영을 통해 스마트팜 분야 전문인력 육성(20개월 과정)', array['신청기간 2026.4.30.(목) ~ 5.29.(금) 15:00까지', '신청방법 스마트팜코리아 누리집(www.smartfarmkorea.net)', '적격심사 6.1.~12.', '서류심사 6.24.~26.', '면접심사 7.6.~8.', '합격자 발표 7.15.', '* 상기 일정은 변경될 수 있음', '전국 4개소 스마트팜 혁신밸리 청년창업 보육센터', '입문(이론) 과정(2개월, 180시간 이상)', '스마트팜 농업기초(경영관리·시설관리·작물생리·품목재배), 스마트팜 관련 정보통신기술 및 데이터 이해·관리 교육 등', '* AI 및 데이터 활용 등 외부 전문 교육기관과 연계한 특강 등 진행', '교육형 실습(6개월, 480시간 이상)', '보육센터 실습 온실과 스마트팜 선도농가 온실 등 현장실습을 활용한 스마트팜 경영 노하우 축적 및 벤치마킹 등', '경영형 실습(12개월, 960시간 이상)', '교육생 책임 하에 영농·경영을 경험해 볼 수 있도록 경영실습 온실 구역 제공(약 330m²/1인) 등', '* 보육센터별 여건에 따라 면적 또는 인원이 다를 수 있음', '스마트팜코리아(콜센터) ☎ 1522-2911', '한국농업기술진흥원 ☎ 063-919-1774(1786)']::text[], null, array['전공에 관계없이 스마트팜 영농기술을 배우고자 희망하는 청년', '1월 1일 기준 18세 이상 ~ 39세 이하', '(주민등록상 ’86. 1. 2. ~ ’08. 1. 1. 출생자)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=61316', null, '제주특별자치도농업기술원 공지사항, 농림축산식품부 보도자료', '2026-11-15', '[{"label":"농림축산식품부: 스마트팜 청년창업 보육센터 교육생 모집","url":"https://www.mafra.go.kr/bbs/home/792/577784/artclView.do"},{"label":"농림축산식품부: 9기 교육생 208명 최종 선발","url":"https://mafra.go.kr/bbs/home/792/578475/artclView.do"}]'::jsonb),
  (17, 'smartfarm-field-practice-pro-2026', '스마트팜 현장실습형 교육생(전문과정) 모집 (2026)', '한국농업기술진흥원 · 제주특별자치도농업기술원 안내', array['영농기술']::text[], array['교육']::text[], 18, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-04-01', '2026-04-30', '2026-04-16', null, array['나. 선발인원 : 200명', '라. 교육기간 : 6개월 * (1단계) 기초과정(40H) + (2단계) 농가 실습(160H)', '마. 신청방법 : 한국농업기술진흥원 누리집 내 ''사업공고'' 게시판 공고문 참고', '신청기간 2026. 4. 1.(수) ~ 4. 30.(목), 15:00 까지', '자부담 재료 및 교재비 30만원', '서류심사 5. 11.(월)~5. 12.(화)', '면접심사 5. 18.(월)~5. 20.(수)', '최종선발안내 5. 29.(금)', '교육과정 희망 권역·품목별 맞춤형 교육 수강의 기회', '기초과정 (1개월 과정, 40시간) 월 10일, 일 4시간 내외 교육 스마트팜 이론(32시간) + 기업형 스마트팜 탐방(8시간)', '선도농가 실습 (5개월 과정, 160시간) 월 4~5일, 일 4~8시간 실습 현장실습형 교육(160시간) *권역·품목별 선도농가', '권역 경기 전라 강원 충청 경상', '품목 딸기 오이 토마토 엽채류', '교육기간 기초과정 6월~7월 선도농가 실습 7월~11월', '신청방법 *자세한 내용은 모집공고를 확인해주세요.', '1 QR코드 접속 → 본인인증 → 신청서 작성', '2 링크 접속 → 본인인증 → 신청서 작성', 'www.스마트팜전문교육.com', '실습지원금 100만원 교육이수 80% 이상 수료시 지원금 지급', '우수 영농 전문가 멘토링 품목별 전문가 현장실습형 교육', '영농창업 사업계획서 체계적 창업 준비 지원', '우수교육생 국외연수 기회', '스마트팜 청년창업 보육생 지원 가산점 스마트팜 보육센터 지원시 가산점 부여', '취·창업 컨설팅 지원 맞춤형 진로 컨설팅', '농업교육 이수시간 200시간 농업교육포털 교육이수시간 인정', '문의처 070-4481-8991', '카카오톡 ''2026년 스마트팜 현장실습형 교육'' 채널 검색 친구추가']::text[], null, array['다. 모집대상 : 스마트팜 영농기술을 배우고자 희망하는 자', '* 2026년 기준 1월 1일 기준 18세 이상(주민등록상 ’08. 1. 1. 포함 이전 출생자)의 대한민국 국적 소지자', '*현장실습형 교육(5개월) 참여 가능한 자']::text[], '{}'::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=61218', null, '제주특별자치도농업기술원 공지사항', '2026-11-15', '[]'::jsonb),
  (18, 'jeju-seogwipo-youth-field-consulting-2026', '청년농업인 영농안정 맞춤형 현장컨설팅 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['영농기술']::text[], array['컨설팅']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-03-05', '2026-03-20', '2026-03-05', '청년농업인의 영농정착과 영농기술 수준 향상을 지원하기 위하여 영농기술 경영상태 진단 분석 후 컨설팅 서비스 제공', array['기 간: 2026. 3 ~ 12월 (기간 컨설팅 5회 이내)', '컨설턴트: 특화작목육성팀장 부창훈, 인력육성팀장 김정훈', '주요내용: 감귤류 재배기술(전정) 요령, 개별 과원관리, 농가경영 개선 교육 등', '3월 - 홍보 및 참여자 신청 접수', '3월~11월 - 청년농업인 개별·모임체 현장 컨설팅 진행', '- 작목별 맞춤형 재배기술 실습 및 농가경영개선 교육', '~12월 - 청년농업인 활동 평가 및 정보교류', '신청기간: 2026.3.5.(목)~3.20.(금) 18:00까지', '신청방법: 이메일(ha3654@korea.kr)로 제출', '문의전화: 정하은 지방농촌지도사(☏ 760-7813)', '[교육시간인정] 컨설팅 대상 농가에 대해 교육시간 2시간/ 회 인정']::text[], null, array['추진대상: 청년농업인4-H회원 및 희망 청년농업인 10명 내외', '농식품부 청년후계농 영농정착 지원사업 대상자 및 4-H청년농업인', '서귀포(남원읍~서귀포시 동지역) 거주자 또는 농장소유자']::text[], array['청년농업인 영농기술강화 현장 컨설팅 신청서 1부']::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=59511', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (19, 'jeju-seogwipo-new-farmer-basic-2026', '신규농업인 기초 교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['예비농', '신규농']::text[], null, '2026-02-05', '2026-04-29', '2026-02-02', '신규농업인에게 체계적인 기초 영농기술 교육과 다양한 농업사례 및 정보를 제공하여 안정적으로 농업·농촌에 정착할 수 있도록 함', array['교육기간: 2026. 3. 4.(수) ~ 4. 29.(수) / 5회 18시간', '교육강사: 기술원 자체 강사 및 선도농업인 등 외부강사 초빙', '※ 상기 일정 및 내용은 사정에 의해 조정될 수 있음.', '- 접수기간: 2026. 2. 5.(목) 09:00 ~ 모집인원 충족시까지', '- 전화접수: ☎ 760-7831, 7832, 7834', '- 방문접수: 서귀포농업기술센터 농촌자원팀', '「농업인 교육 운영관리」지침에 의거하여 교육생 관리', '- 전체 교육시간의 80% 이상 참석: 수료', '- 전체 교육시간의 30% 이상 참석: 이수, 실 참석시간만큼 인정', '- 전체 교육시간의 30% 미만 참석: 미수료, 교육시간 불인정']::text[], null, array['교육대상(아래 기준 중 1개 이상 해당) 및 인원: 50명', '- 농촌 이주 5년 이내 귀농인', '- 농업경영체 등록 5년 이내 신규농업인 (* 농업경영체 제출)', '- 만 40세 미만 청장년층 (* 귀농 여부 및 지역과 상관없이 지원 가능)', '- 예비귀농인 (* 공인된 기관에서 실시한 귀농교육을 35시간 이상 이수하고 농어촌지역으로 이주계획이 구체적으로 확인되는 경우)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=59360', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (20, 'jeju-center-new-farmer-basic-tech-2026', '신규농업인 기초영농기술교육 (제주농업기술센터, 2026)', '제주특별자치도 제주농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['신규농']::text[], null, '2026-03-30', '2026-04-03', '2026-03-30', '신규농업인 등에게 체계적인 기초영농기술교육과 농업정보 제공을 통하여 성공적인 농업·농촌에 정착할 수 있도록 지원', array['교육기간: 2026. 4. 20. ~ 6. 1. / 기간내 6회 18시간', '장소: 제주농업기술센터 농업인교육관, 센터 실증포장 등', '강사: 센터 분야별 담당자 및 외부강사 등', '교육내용', '- 관내 주산 작목 중심 영농기술 기초 이론', '- 농약사용 기초, 토양환경과 양분관리 등 신규농업인 맞춤형 기초교육', '접수기간: 2026. 3. 30.(월) ~ 모집인원 충족 시까지(선착순 접수)', '접수방법: 제주농업기술센터 농촌자원팀 전화 및 방문접수(☎760-7722~3)', '※온라인 신청정원 외 신청자는 전화문의 바랍니다.', '문의전화 064-760-7722~3', '「농업인 교육 운영관리」 지침에 의거하여 교육생 관리', '- 전체 교육시간의 80% 이상 참석 : 수료 처리', '- 전체 교육시간의 30% 이상 참석 : 실제 이수시간 만큼 인정', '- 전체 교육시간의 30% 미만 참석 : 미수료, 교육시간 불인정']::text[], null, array['교육대상: 관내 신규농업인 및 청년농업인 등 40명', '- 농촌 이주 5년 이내 귀농인 또는 농업경영체 등록 5년 이내 신규농업인', '- 만 40세 미만 청장년층', '- 예비귀농인(공인된 기관에서 실시한 귀농교육을 35시간 이상 이수 필수)', '접수순위(정원 외 대기자 발생 시)', '- 1순위: 관내 신규농업인 및 청년농업인 등', '- 2순위: 관내 관심 농업인', '- 3순위: 관외 신규농업인 및 청년농업인 등']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jeju/technologycenter/education/jeju.htm?act=view&seq=765', null, '제주농업기술센터 교육신청', '2026-11-15', '[]'::jsonb),
  (21, 'jeju-seogwipo-smartfarm-basic-2026', '스마트팜 활용 기초 교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-05-07', '2026-06-18', '2026-05-04', null, array['교육기간: 2026. 5. 27.(수) ~ 6. 18.(목) / 4회 17시간(※ 6. 10.(수) 현장교육)', '교육장소: 서귀포농업기술센터 농업인교육관 및 농업 현장 등', '교육내용', '- 스마트팜 기초 이론 및 스마트팜 현황, 협업사례', '- 스마트팜 관련 유관기관 및 우수 농가 견학', '- 농장 전기 기본회로 및 전동기 회로구성 및 실습', '※ 상기 일정 및 내용은 사정에 의해 변경될 수 있음', '교육신청 방법', '- 접수기간: 2026. 5. 7.(목) 09:00 ~ 모집인원 마감시까지', '- 전화접수: ☎ 760-7831, 7832', '- 방문접수: 서귀포농업기술센터 농촌자원팀', '등록 및 출결 관리', '- 교육등록: 사전신청 접수자는 교육신청서 당일 제출', '- 출결관리: 출석부 비치하고 본인 서명만 인정', '「농업인 교육 운영관리」 지침에 의거하여 교육생 관리', '- 전체 교육시간의 80% 이상 참석: 수료, 총 교육시간 인정', '- 전체 교육시간의 30% 이상 80% 미만 참석: 이수, 실 참석시간 인', '- 전체 교육시간의 30% 미만 참석: 미수료, 교육시간 불인정']::text[], null, array['교육대상: 관내(서귀포시 동지역~남원읍) 교육을 희망하는 농업인 30명']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=61299', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (22, 'jeju-seogwipo-rural-convergence-pro-2026', '농촌융복합 활성화 전문과정 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['판로', '영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-05-28', '2026-06-30', '2026-05-19', '농업을 기반으로 생산․가공․유통 및 체험관광을 연계한 농촌융복합산업을 주도할 경영체 육성 및 경영개선 배양을 통한 부가가치 향상 도모', array['교육기간: 2026. 6. 23.(화) ~ 6. 30.(화) 3회 14시간', '장 소: 서귀포센터 농업인교육관 및 농촌융복합 사업장', '교육내용: 농촌관광 소비 트렌드와 고객 맞춤형 소비스 전략, 팜파티 플래닝 이론 및 연출 실습, 현장 교육 등', '※ 교육일정 및 교육내용은 변경될 수 있습니다.', '접수기간: 2026. 05. 28.(목) 09:00 ~ 모집 인원 마감 시(선착순 접수)', '수료(이수)증 발급 기준', '- 수료증: 전체 교육 기간(또는 시간) 80% 이상 출석 한 경우', '- 이수증: 전체 교육 기간(또는 시간) 30% 이상 80% 미만 출석 한 경우']::text[], null, array['대상 및 인원: 관내 농촌융복합사업자 및 교육희망자 30명']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=61386', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (23, 'jeju-seogwipo-gap-basic-2026', '농산물우수관리(GAP) 인증 기본교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['판로', '영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-09-18', '2026-10-07', '2026-09-14', '고품질 안전 농산물 생산으로 농가 경영개선 유도 및 소득향상을 위한 농산물우수관리(GAP) 인증 교육', array['교육일시: 2026. 10. 7.(수) 14:00~16:00', '교육장소: 서귀포농업기술센터 농업인교육관', '교육강사: 서귀포농업기술센터 지방농촌지도사 강지호', '교육내용', '- 농산물우수관리 기준 및 농산물우수관리인증제도', '- 농산물이력추적관리제도 관련 규정', '- 농산물우수관리 실천 요령 및 농약 안전사용 등', '※ 상기 일정 및 내용은 사정에 의해 변경될 수 있습니다.', '- 접수기간: 2026. 9. 18.(금) 09:00 ~ 모집인원(100명) 충족시까지', '- 전화접수: ☎ 760-7831, 7832, 7834', '- 방문접수: 서귀포농업기술센터 농촌자원팀', '※ 추가인원은 교육당일 현장 접수']::text[], null, array['교육인원: 교육을 희망하는 농업인 100명 내외']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?act=view&seq=61977', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (24, 'mafra-young-farmer-settlement-2026-1st', '청년농업인 영농정착지원사업 (2026년 1차 선발)', '농림축산식품부 · 제주시·서귀포시 접수', array['초기자금', '농지']::text[], array['보조금', '융자']::text[], 18, null, '만 18세 이상~만 40세 미만(1985~2008년도 출생자)', '{}'::text[], null, 3, array['예비농', '신규농']::text[], null, '2025-11-05', '2025-12-11', '2025-11-04', null, array['이번 1차 모집에서는 2,000명을 우선 선발하고, 하반기 중 2차 모집을 통해 예산 범위 내에서 잔여 인원을 추가 선발할 예정이다.', '- 2025년 11월 5일부터 12월 11일까지 농림사업정보시스템을 통해 접수', '선발된 청년농업인에게는 최장 3년간 월 최대 110만 원의 영농정착지원금과 함께 농지·시설 매입 및 임차를 위한 후계농자금, 농신보 우대보증, 농지 임대 우선지원 등 다양한 연계 지원이 제공된다.', '다만, 후계농자금은 별도의 자금 배정 절차를 거쳐야 하며, 최종 지원 금액은 개인 신용 평가 등 대출 취급기관의 심사 결과에 따라 달라질 수 있으므로 사전 상담을 권장한다.', '기존에는 지자체가 서류 및 면접 평가를 모두 수행했으나, 2026년부터는 정량지표 영역의 서류 평가와 면접 평가는 지자체가, 정성지표 영역의 서류 평가는 농식품부가 구성한 평가위원회가 담당하여 평가의 공정성과 변별력을 강화한다.', '또한 양에서 질 중심의 청년농업인 육성을 위해 선정된 청년농들을 대상으로 지자체·품목 조합 중심의 사전 교육도 실시할 계획이다.', '2026년 청년농업인 영농정착지원사업에 지원하려는 청년은 2025년 12월 11일까지 농림사업정보시스템(uni.agrix.go.kr)을 통해 신청하면 된다.', '사업 지침과 관련 정보는 ‘탄탄대로’(youngfarmer.greendaero.go.kr)에서 확인할 수 있으며, 궁금한 사항은 청년농업인 안내 콜센터(1670-0255)로 문의하면 된다.', '사업대상자는 12월 진행되는 서류 평가와 면접 평가를 거쳐 2026년 1월 중 최종 확정된다.']::text[], null, array['만 18세 이상~만 40세 미만(1985~2008년도 출생자)의 독립 영농경력 3년 이하인 청년농업인 또는 예정자 중, 소득과 재산이 일정 수준* 이하인 경우 신청할 수 있다.', '* 본인세대의 건강보험료 산정액(본인부담액 또는 부과액) 기준으로 기준중위소득 140% 초과한 경우 신청 불가']::text[], '{}'::text[], 'https://www.mafra.go.kr/bbs/home/792/575810/artclView.do', 'https://uni.agrix.go.kr', '농림축산식품부 보도자료, 제주시 모집 안내(보도)', '2026-11-15', '[{"label":"뉴스라인제주: 제주시 2026년 영농정착지원 1차 모집","url":"http://www.newslinejeju.com/news/articleView.html?idxno=164233"},{"label":"농림사업정보시스템: 1차 신청서 제출 안내","url":"https://uni.agrix.go.kr/docs6/cert/mobileCert/agreePopup.html"}]'::jsonb),
  (25, 'mafra-youth-startup-scholarship-2026-2h', '청년창업농 장학금 (2026년 2학기)', '농림축산식품부 · 한국농어촌희망재단', array['영농기술']::text[], array['보조금']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-06-01', '2026-06-30', '2026-05-20', '(지원 목적) 농업‧농촌‧농산업분야 청년인력 유입 및 정착구조 마련을 위해 대학졸업 후 영농‧농림축산식품분야 취‧창업 조건부 장학금 지원', array['(지원 내용) 학기당 등록금 및 학업장려금 250만원', '* 학업장려금 : 안정적인 학업여건 조성을 위해 지급하는 생활비성 지원금', '(지원 규모) ‘26년 2학기 900명 내외, 8,600백만원', '(심사‧선발) 신청(학생) → 학교추천(심사) → 서류심사 → 보증보험가입 → 선발', '올해 2학기 청년창업농장학금 신청은 오는 6월 1일부터 6월 30일까지 진행하며, 농어촌희망재단 누리집(www.rhof.or.kr)을 통해 접수할 수 있다.', '(의무종사) 졸업 후 장학금 수혜 횟수에 해당하는 기간(수혜학기당 6개월)만큼 영농 및 농림축산식품분야에 취·창업', '* 의무종사 미이행 시 장학금(등록금, 학업장려금) 환수', '(의무교육) 신규 장학생 25시간, 계속 장학생 20시간 필수 이수', '* 의무교육 미이행 시 차기 학기 장학금 지원중단, 의무종사는 유지']::text[], null, array['(지원 대상) 전공에 관계없이 재학 중인 대학 3학년생 이상(최대 4학기)', '- 농식품분야 학과 학생은 1학년 2학기부터 지원(최대 7학기)', '- 직전 학기 성적 70점, 이수학점 12학점 이상, 만 40세 미만인 자']::text[], '{}'::text[], 'https://www.mafra.go.kr/bbs/home/792/577966/artclView.do', 'https://www.rhof.or.kr', '농림축산식품부 보도자료·홍보물', '2026-11-15', '[{"label":"농림축산식품부: 대한민국 농업의 미래를 이끌어갈 청년을 찾습니다 (홍보물)","url":"https://www.mafra.go.kr/bbs/home/796/578119/artclView.do"}]'::jsonb),
  (26, 'mafra-youth-rural-experience-program-2026', '청년참여형 소규모 농촌체험프로그램 개발사업 (2026)', '농림축산식품부 농촌경제과', array['네트워크(지역사회 관계)', '판로']::text[], '{}'::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-04-01', '2026-05-11', '2026-03-31', null, array['청년 참여를 희망하는 마을 26개소를 대상으로 소규모 농촌체험 프로그램 개발사업을 추진하고자 하는 청년을 4월 1일부터 5월 11일까지 지방정부, 시·도 농촌융복합지원센터, 웰촌 홈페이지 등을 통해 공개 모집할 예정이며, 청년은 참여 희망 마을 중 1개소를 선택하여 신청서와 사업계획서를 제출하여야 한다.', '최종적으로 심사를 거쳐 5개 농촌체험휴양마을과 5명의 청년을 선정할 계획이며, 선정된 청년과 농촌체험휴양마을 및 소관 전국농촌체험휴양마을 도협의회 간 협약을 체결한 후 전문 컨설팅사의 지원을 받아 참여 청년은 해당 농촌체험휴양마을의 특색 있는 소규모 농촌관광 프로그램 기획·개발, 운영, 홍보 등을 담당하게 된다.', '협약 체결 이후에는 홍보, 전문가 컨설팅, OTA 플랫폼 연계 판매 지원 등을 통해 청년 주도의 특색 있는 농촌관광 상품이 원활하게 운영될 수 있도록 지원도 병행하여 육성해 나갈 계획이다.', '올해 선정된 5개 마을은 ▲강원 홍천 무궁화마을 ▲충북 옥천 향수뜰마을 ▲충남 당진 왕매실마을 ▲경북 칠곡 학수고대마을 ▲제주 소길농촌체험휴양마을이며, 힐링형과 식도락형 등 최근 관광 트렌드를 반영한 체험 프로그램을 개발할 예정이다.']::text[], null, array['- 농촌체험휴양마을의 농촌관광 체험프로그램 기획·개발에 참여할 청년 모집 -', '농촌의 고령화 등으로 운영에 어려움을 겪고 있어 청년 참여를 통해 활성화가 필요한 농촌체험휴양마을을 대상으로 하며, 3월 11일부터 24일까지 참여 희망 마을을 공모한 결과 26개의 농촌체험휴양마을이 지방정부의 추천을 받아 참여를 신청하였다.']::text[], '{}'::text[], 'https://www.mafra.go.kr/bbs/home/792/577460/artclView.do', null, '농림축산식품부 보도자료', '2026-11-15', '[{"label":"농림축산식품부: 청년과 농촌체험마을 협약식 (2026.5.29)","url":"https://www.mafra.go.kr/bbs/home/792/578054/artclView.do"}]'::jsonb),
  (27, 'mafra-pre-farmer-mentoring-pilot-2026', '예비농업인 역량강화(멘토링·교육) 시범사업 (2026)', '농림축산식품부', array['영농기술', '네트워크(지역사회 관계)']::text[], array['교육', '컨설팅']::text[], null, null, null, '{}'::text[], null, null, array['예비농']::text[], null, '2026-01-28', '2026-02-20', '', '2026년 예비농업인 200명을 대상으로 맞춤형 멘토링 및 현장·품목중심 영농교육 지원을 통해 창농역량 강화', array['ㅇ 신청기간: 2026. 1. 28.(수) ~ 2.20.(금)', '1. 28.(수) ~ 2. 20.(금) 18:00까지', 'ㅇ 접수처: 영농정착지원 사업 선정지역 시·군·구 (별첨1 참고)', '지원사항(멘토링+교육 모두 필수참여)', 'ㅇ 멘토링 : 예비농업인이 희망하는 분야(창업준비, 영농기술, 농촌생활, 경영관리 등)의 멘토를 매칭하여 창농준비 과정에서 발생하는 다양한 애로사항을 밀착·맞춤형으로 해소(약 6개월)', '* (멘토) 분야별 전문가 및 우수 선배농업인', '* (형식) 대면 이론·실습교육(최대 10회, 멘토·멘티 농장 등 실습)', '비대면 맞춤형 지도·상담(수시, 화상회의·메신저 등 활용)', 'ㅇ 교육 : 지방정부의 예비·청년농업인 역량강화 교육프로그램에 우선적으로 선발하여 교육 지원(지방정부별 기간 상이)', '- 신규농업인영농기술향상(기초영농기술교육, 현장실습교육) 및 농업인대학 등 다양한 교육과정을 예비농업인 수요에 맞춰 운영하되, 지방정부별 교육인프라 및 운영여건에 따라 차별화', 'ㅇ 선발방법 : 제출한 신청서에 기반하여 각 시·도*에서 선발', '* 영농정착지원사업 선발인원을 기준으로 시·도별 배분하되, 신청인원 및 시·도별 여건에 따라 조정 가능', '* 접수 : 선정지역 시·군·구 담당자 이메일, 우편 및 방문접수(별첨1 시·군·구 접수처 확인)', '* 지원서 다운로드: 농림축산식품부 홈페이지, 시·도 및 시·군·구 홈페이지, 탄탄대로', 'ㅇ 2026.2.27.(금), 합격자 대상 개별 문자 및 e-mail 전송', '* 최종합격자 선정 안내 전 각 지방자치단체의 교육과정 우선선발에 따른 별도 안내가 갈 수 있습니다.', '- 소속 시·도에서 운영하는 교육과정은 시·도별로 차이가 있을 수 있으며, 원하는 교육과정이 있을 경우 신청서의 ‘희망교육’란에 작성하시면 최대한 수요를 반영할 수 있도록 선발 과정에서 참고하겠으나, 반드시 반영되는 것은 아닙니다', '- 교육생 모집·선발 과정에서 교육과정에 따라 필요한 서류를 추가제출 요청할 수 있습니다.', '* 신청시 반드시 공고문 및 유의사항을 확인하시기 바랍니다.', '관련문의 멘토링 – 청년농업인 상담센터 1670-0255 | 선정지역 시·군·구 담당자']::text[], null, array['ㅇ 2026년 청년농업인 영농정착지원 사업 선발자 중 비농업계 학교 출신 영농미개시 예비농업인 200명']::text[], array['ㅇ 신청서와 개인정보 수집 동의서를 작성하여 선정지역 시·군·구 제출(양식1·2)']::text[], 'https://www.mafra.go.kr/bbs/home/791/594056/download.do', null, '농림축산식품부 모집 홍보물', '2026-11-15', '[]'::jsonb),
  (28, 'korea-af-univ-2027-admission', '국립한국농수산대학교 2027학년도 신입생 모집', '국립한국농수산대학교', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['예비농']::text[], null, '2026-09-07', '2026-10-23', '2026-06-10', null, array['- 수시 1차(원서 접수 9.7~30, 432명 선발), 수시 2차(원서접수 10.12~23, 138명 선발)', '한농대에서는 18개 전공별로 수시 모집을 통해 신입생을 선발한다.', '수시 1차 원서 접수는 9월 7일부터 9월 30일까지 이며, 4개 전형에 총 432명(일반전형 231, 농수산전형 124, 사회통합전형 18, 지역균형전형 59)을 선발할 예정이다.', '수시 2차(일반전형)는 138명을 모집하며, 원서 접수는 10월 12일부터 10월 23일까지이다.', '원서 접수는 수시 1차 9월 7일~9월 30일, 수시 2차 10월 12일~10월 23일이며, 합격자 발표는 수시 1차 11월 19일, 수시 2차 12월 17일이다.', '신입생 선발은 2단계로 진행된다.', '1단계에서는 고교 내신 성적(70점)과 출결(30점) 점수를 합산해 모집인원의 3배수 내외를 선발하며, 2단계에서는 1단계 합격자를 대상으로 면접 평가를 통해 최종합격자를 선발한다.', '수시 2차의 경우, 1단계에서 영농 기반(5점)과 농수산 관련 자격증(최대 2점)을 가진 응시자에 대해 가산점을 부여하고 있다.', '* 단, 검정고시 합격자 및 외국고 졸업(예정)자는 교과성적 100%로 평가', '* 필수서류 미제출자, 지원 자격 부적격자 등은 1단계 평가에서 제외', '세부내용은 한농대 누리집 2027학년도 신입생 모집 요강을 참고하면 된다.', '한농대는 국내 유일의 농수산 특성화 국립대학교(3년제)로, 정예 농수산 인재 양성을 위해 재학생들에게 수업료, 실습비, 기숙사비와 식비 등을 국가에서 지원하고 있다.', '주요 교육내용은 농수산 분야의 이론과 실무, 창업 교육 등이다.', '1학년과 3학년은 학교에서 농어업 기초 이론과 인문 소양, 농어업 승계 및 창업 관련 교육을 이수하게 되며, 2학년은 선진 농어업 경영체 등에서 1년간 현장실습 교육을 이수하게 된다.']::text[], null, array['한농대 신입생 선발에 응시하고자 하는 자는 고교 졸업(예정)자 또는 동등 이상의 학력을 가진 자로서, 농수산분야에서 미래를 개척하려는 대한민국 국민이라면 누구나 지원 가능하다.', '수시 1차 일반전형 고등학교 졸업(예정) 이상 학력자(단, 농수산계 고교 출신자는 제외)', '농수산전형 농수산계 고교 졸업(예정)자', '사회통합전형 고등학교 졸업(예정) 이상 학력자 중 아동복지시설 출신자, 기초생활수급자, 차상위계층, 한부모가정 지원대상자, 다문화가정 자녀, 북한이탈주민 및 그 자녀', '지역균형전형 경상권(경북‧경남‧대구‧부산‧울산), 충청권(충북‧충남‧대전‧세종), 강원, 제주 지역 소재 고교 졸업(예정)자', '수시 2차 일반전형 고등학교 졸업(예정) 이상 학력자(농수산계 고교 출신자 포함)', '* 외국 국적자는 지원 불가']::text[], '{}'::text[], 'https://mafra.go.kr/bbs/home/792/578928/artclView.do', 'https://www.af.ac.kr', '농림축산식품부·한국농수산대학교 보도자료', '2026-11-15', '[{"label":"농림축산식품부: 한농대 2027학년도 신입생 모집요강 발표","url":"https://www.mafra.go.kr/bbs/home/792/578140/artclView.do"}]'::jsonb),
  (29, 'mafra-return-farm-startup-housing-2026', '귀농 농업창업 및 주택구입 지원사업 (2026)', '농림축산식품부 · 시·군 접수', array['주거', '초기자금']::text[], array['융자']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, null, null, '', null, '{}'::text[], null, '{}'::text[], '{}'::text[], null, null, '농림축산식품부 2026년 시행지침(군산시 게시본), 지자체 모집 보도', '2026-11-15', '[]'::jsonb),
  (30, 'mafra-rural-startup-contest-2026', '농촌창업 경진대회 (2026, 농촌 어메니티·로컬푸드 분야)', '농림축산식품부', array['판로', '초기자금']::text[], array['컨설팅']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-03-16', '2026-04-10', '2026-03-15', '농촌의 유무형 자원과 아이디어를 결합한 유망 창업기업을 발굴하는 경진대회입니다. 2026년에는 농촌 어메니티 창업 분야(10팀 이내)를 3월 16일 09:00~4월 10일 18:00 농촌융복합산업 누리집(www.6차산업.com)에서 모집했고, 로컬푸드 분야(5팀 이내)는 4월 중 별도로 공모할 계획이었습니다. 선정 팀은 장관상과 상금, 민간 기업 연계 보육을 받고, 2027년부터 지방정부와 연계한 최대 1억 원 규모의 사업화 자금도 지원받을 수 있습니다.', null, null, array['농촌 어메니티 분야: 농촌지역 유·무형 자원을 활용한 혁신적 사업모델을 가진 업력 7년 미만 창업자', '로컬푸드 분야: 농촌지역 농특산물을 활용하는 식품·제조 기업 (4월 중 별도 공모)', '선정: 서류·발표평가']::text[], '{}'::text[], 'https://www.mafra.go.kr/bbs/home/792/595609/download.do', null, '농림축산식품부 보도자료', '2026-11-15', '[]'::jsonb),
  (31, 'mafra-gatsaeng-internship-2026', '갓생 인턴십 (2026, 농업 분야 청년 인턴)', '농림축산식품부', array['영농기술', '네트워크(지역사회 관계)']::text[], array['교육']::text[], 18, 34, null, '{}'::text[], null, null, '{}'::text[], null, '2026-05-21', '2026-06-24', '2026-05-20', '스마트팜·농촌비즈니스·푸드테크 기업 5곳에서 3주간(7월 13일~31일) 프로젝트를 수행하며 농업 분야 직무를 체험하는 인턴십입니다. 24명을 뽑았고, 식비·교통비 등을 포함한 활동비 201만 원을 지원했습니다. 올해부터 멘토링 프로그램이 추가되었습니다. 참여 기업은 경기·전남·서울·충남 소재입니다.', null, null, array['만 18세 이상 34세 이하 청년', '신청: 가치갓생 공식 누리집']::text[], '{}'::text[], null, null, '농림축산식품부 발표(언론 보도)', '2026-11-10', '[{"label":"헤럴드경제: 농식품부, 갓생 인턴십 청년 24명 모집","url":"https://www.heraldk.com/article/2026051918000064601"}]'::jsonb),
  (32, 'jeju-si-youth-farmland-rent-2026-h1', '제주시 청년농업인 농지 임대료 지원 (2026년 상반기)', '제주시 친환경농정과', array['농지']::text[], array['보조금']::text[], 19, 45, null, array['제주시']::text[], null, null, array['기존 농업경영체']::text[], true, null, '2026-05-04', '', '농지은행을 통해 계약한 농지 임대료의 50%를 농가당 최대 100만 원까지 지원합니다(매년 신청 시 최대 3년). 상반기 신청은 5월 4일 18:00까지 방문 또는 이메일로 받았습니다. 예산을 넘으면 비축농지 임대형 스마트팜, 맞춤형 농지지원사업, 농지임대수탁·과원규모화·경영회생 임대사업 순으로 우선 지원합니다. 같은 사업의 하반기 모집은 별도 카드로 정리돼 있습니다. 문의: 064-728-3314', null, null, array['제주시에 주소를 두고 거주하며 농업경영체를 등록한 만 19세~45세 청년농업인 (1981.1.1.~2007.12.31. 출생)', '한국농어촌공사 농지은행 사업으로 농지 임대차 계약을 체결한 실경작자', '2026년 1월 1일 기준 (신규계약 포함) 임대차 계약 유지']::text[], array['사업신청서', '농업경영체등록확인서', '농지임대차계약서', '임대료 납부약정서', '주민등록등본', '통장사본']::text[], null, null, '제주시 시정뉴스 (제주도민일보 게재)', '2026-11-10', '[{"label":"제주도민일보: 2026년 청년농업인 농지 임대료 지원사업 신청·접수 (제주시)","url":"https://www.jejudomin.co.kr/news/articleView.html?idxno=318447"}]'::jsonb),
  (33, 'jeju-agri-tech-pilot-2026-5th', '농업기술보급 시범사업 5차 (제주특별자치도 농업기술원, 2026)', '제주특별자치도 농업기술원 기술지원조정과', array['영농기술']::text[], array['보조금']::text[], null, null, null, array['제주특별자치도 전체']::text[], null, null, '{}'::text[], true, '2026-08-24', '2026-09-04', '2026-08-24', '새로운 농업기술을 농가에 보급하는 시범사업 5차 신청입니다(제주특별자치도 공고-2026-2783호). 분야는 ''ESS 활용 시설하우스 자연재해 경감 시범'', ''돈사 냄새 모니터링 및 저감 기술보급 시범''이었습니다. 8월 24일~9월 4일 18시까지 가까운 농업기술센터(축산 분야는 축산생명연구원)에 방문·우편·이메일로 접수했습니다. 6차 신청은 별도 카드로 정리돼 있습니다. 문의: 064-760-7532', null, null, array['제주특별자치도에 주소를 둔 농업인(단체) 및 법인', '시범사업을 충실히 이행하고 포장을 주변 농가 교육장으로 제공할 수 있는 자', '제외: 전년도 2천만 원 이상 또는 최근 2년 연속 보조금 수혜자, 농업 외 전업 직업자, 농업 외 소득 3,700만 원 초과자 등']::text[], array['사업신청서', '농업경영체등록확인서', '주민등록등본', '가족관계증명서', '건강보험 자격득실확인서', '농지대장', '지방세납세증명서']::text[], 'https://agri.jeju.go.kr/agri/notice/notice.htm?act=view&seq=61886', null, '제주특별자치도 농업기술원 공고', '2026-11-10', '[{"label":"제주농업기술센터: 2026년 농업기술보급 시범사업 5차 신청 공고","url":"https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=61888"}]'::jsonb),
  (34, 'jeju-seogwipo-new-mandarin-variety-edu-2026', '농업기술원 육성 신품종 만감류 재배기술 교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-03-23', '2026-03-31', '2026-03-19', '농업기술원이 육성한 신품종 만감류(가을향, 우리향, 달코미, 설향)의 재배기술을 배우는 교육입니다. 4월 8일과 9월 2일 총 2회 8시간이었고, 선착순 50명을 모집했습니다. 접수는 3월 23일~31일이었습니다.', null, null, array['교육을 희망하는 관내 농업인 (선착순 50명)', '신청: 전화 또는 방문']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_20260910091528497ef18&enfcInstNm=SEOGWIPO&pageIndex=1', null, '제주특별자치도 농업기술원 영농교육, 서귀포농업기술센터 공지사항', '2026-11-10', '[{"label":"서귀포농업기술센터: 신품종 만감류 재배기술 교육생 모집","url":"https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=2&act=view&seq=59601"}]'::jsonb),
  (35, 'jeju-seogwipo-citrus-core-tech-edu-2026', '감귤분야 핵심기술교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터 농촌자원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-02-20', '2026-03-06', '2026-02-04', '만감류 I반(한라봉·천혜향 중심), 만감류 II반(레드향·황금향 중심), 노지감귤 등 3과정 12회 교육입니다. 3월 9일~9월 10일 14:00~17:00 서귀포농업기술센터 농업인교육관에서 열렸고 과정별 100명을 모집했습니다. 1인 1과정만 신청할 수 있었습니다. 접수: 760-7832, 7834, 7831', null, null, array['교육을 희망하는 관내 농업인 (과정별 100명)', '신청: 전화 또는 방문 (1인 1과정)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_202609091750566177bca&enfcInstNm=SEOGWIPO&pageIndex=1', null, '서귀포농업기술센터 공지사항, 농업기술원 영농교육', '2026-11-10', '[{"label":"서귀포농업기술센터: 2026년도 감귤분야 핵심기술교육 추진계획","url":"https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=2&act=view&seq=59380"}]'::jsonb),
  (36, 'jeju-seobu-citrus-cultivation-edu-2026', '감귤류 재배기술교육 (서부농업기술센터, 2026)', '제주특별자치도 서부농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-02-23', '2026-03-03', '2026-02-23', '노지감귤(3월 10일~9월 8일, 4회, 120명), 만감류 A반(3월 12일~9월 10일), 만감류 B반(3월 13일~9월 11일)으로 운영된 재배기술교육입니다. 노지감귤 과정은 월별 중점관리 요령 등을 다뤘고 서부농업기술센터 농업인 교육관에서 열렸습니다. 접수는 2월 23일 09:00~3월 3일 18:00였습니다. 문의: 064-760-7931~2', null, null, array['교육 대상은 과정 안내에 명시되지 않음 (센터 문의)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_20260911172228927fe1c&enfcInstNm=SEOBU&pageIndex=1', null, '제주특별자치도 농업기술원 영농교육', '2026-11-10', '[{"label":"영농교육: 감귤류 재배기술교육 (만감류 A반)","url":"https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_20260911174626260de9b&enfcInstNm=SEOBU&pageIndex=1"},{"label":"영농교육: 감귤류 재배기술교육 (만감류 B반)","url":"https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_202609111748324939841&enfcInstNm=SEOBU&pageIndex=1"}]'::jsonb),
  (37, 'jeju-seogwipo-chatgpt-edu-2026', '챗GPT 활용 교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-08-28', '2026-09-17', '2026-08-20', '농업인을 위한 챗GPT 활용 교육입니다. 9월 15일·17일 총 2회 14시간, 서귀포농업기술센터 2층 회의실에서 20명 규모로 열렸습니다. 접수는 8월 28일 09:00부터 정원이 찰 때까지였고, 마감일 칸에는 교육 종료일을 표시했습니다. 구글 계정과 노트북을 준비해야 했습니다.', null, null, array['교육을 희망하는 관내 농업인 (20명)', '구글 계정 필수, 노트북 지참']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=1&act=view&seq=61873', null, '서귀포농업기술센터 공지사항', '2026-11-10', '[]'::jsonb),
  (38, 'jeju-center-women-machinery-edu-2026', '여성농업인 농업기계 및 하반기 경정비 교육 (제주농업기술센터, 2026)', '제주특별자치도 제주농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-09-02', '2026-10-21', '2026-08-20', '여성농업인 농업기계 교육(25명)과 농업기계 경정비 교육(25명)을 10월 13일~21일 제주농업기술센터 농기계임대사업소와 실습포장에서 운영했습니다. 9월 2일 08:30부터 방문·전화 선착순 접수였고, 마감일 칸에는 교육 종료일을 표시했습니다. 접수: 760-7746~9', null, null, array['교육 희망 대상자 (총 50명)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=61877', null, '제주농업기술센터 공지사항', '2026-11-10', '[]'::jsonb),
  (39, 'jeju-center-machinery-safety-edu-2026-h2', '하반기 농업기계 안전이용 교육 (제주농업기술센터, 2026)', '제주특별자치도 제주농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-08-05', '2026-10-28', '2026-07-22', '농업기계를 안전하게 쓰는 방법을 배우는 교육입니다. 9월 15일~10월 28일 기수당 25명, 총 125명 규모로 제주농업기술센터 농기계임대사업소와 실습포장에서 열렸습니다. 8월 5일 08:30부터 방문·전화 선착순 접수였고, 마감일 칸에는 교육 종료일을 표시했습니다. 문의: 760-7746~9', null, null, array['교육 희망 대상자 (총 125명, 기수당 25명)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=61750', null, '제주농업기술센터 공지사항', '2026-11-10', '[]'::jsonb),
  (40, 'jeju-center-machinery-basic-repair-edu-2026-h1', '농업기계 기초 및 상반기 경정비 교육 (제주농업기술센터, 2026)', '제주특별자치도 제주농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-05-07', '2026-06-17', '2026-04-27', '농업기계 기초 교육(20명)과 경정비 교육(25명)을 6월 9일~17일 제주농업기술센터 농기계임대사업소와 실습포장에서 운영했습니다. 5월 7일 08:30부터 방문·전화 선착순 접수였고, 마감일 칸에는 교육 종료일을 표시했습니다. 접수: 760-7746~9', null, null, array['교육 희망 대상자 (총 45명)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=61266', null, '제주농업기술센터 공지사항', '2026-11-10', '[]'::jsonb),
  (41, 'jeju-center-farmwork-safety-consulting-2026', '농작업 안전보건관리 컨설팅 (제주농업기술센터, 2026)', '제주특별자치도 제주농업기술센터', array['영농기술']::text[], array['컨설팅']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-03-09', '2026-04-23', '2026-03-09', '농작업 안전관리자가 농가를 직접 찾아 위험성평가를 하고 현장 맞춤형 안전보건관리 컨설팅을 무상으로 제공합니다. 110농가를 모집했고 컨설팅은 5월 1일~10월 31일 진행되었습니다. 모집은 3월 9일~4월 23일이었고 정원이 차지 않으면 연장될 수 있었습니다.', null, null, array['제주농업기술센터 관내 현장 컨설팅을 희망하는 농업경영주', '1순위: 5인 이상 고용 농업경영주, 2순위: 고용이 있는 농업경영주', '신청: 방문 또는 이메일 (문의 064-760-7742)']::text[], array['농작업 안전보건관리 컨설팅 신청서 (양식 1)', '개인정보 수집·이용 및 제3자 제공 동의서 (양식 2)']::text[], 'https://agri.jeju.go.kr/jeju/notice/notice.htm?act=view&seq=59533', null, '제주농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (42, 'jeju-rural-development-fund-loan-2026-h2', '지역농어촌진흥기금 융자 지원 (제주특별자치도, 2026년 하반기)', '제주특별자치도', array['초기자금']::text[], array['융자']::text[], null, null, null, array['제주특별자치도 전체']::text[], null, null, '{}'::text[], null, null, '2026-07-20', '2026-07-03', '농어가 경영비 부담을 덜기 위한 2,500억 원 규모의 저리 융자(대출)입니다. 금리는 연 0.7%이고, 농어가는 최대 1억 원, 생산자단체는 최대 3억 원까지 빌릴 수 있습니다. 운영자금은 2년(1회 연장 가능), 시설자금은 3년 거치 5년 균분상환입니다. 7월 20일까지 주소지 관할 읍·면사무소와 동 주민센터에서 신청을 받았습니다.', null, null, array['농업·임업·축산업·수산업을 주업으로 하는 도내 농어가와 생산자단체', '융자 한도: 농어가 최대 1억 원, 생산자단체 최대 3억 원', '신청처: 주소지 읍·면사무소, 동 주민센터']::text[], '{}'::text[], null, null, '제주특별자치도 발표(언론 보도)', '2026-11-15', '[{"label":"파이낸셜뉴스: 제주도 2026년 하반기 지역농어촌진흥기금 융자 신청 접수","url":"https://www.fnnews.com/news/202607031055443436"}]'::jsonb),
  (43, 'jeju-farmer-allowance-2026', '농민수당 (제주특별자치도, 2026)', '제주특별자치도', array['초기자금']::text[], array['보조금']::text[], null, null, null, array['제주특별자치도 전체']::text[], 2, null, '{}'::text[], true, '2026-03-09', '2026-03-31', '2026-03-09', '농업인에게 지급하는 농민수당입니다. 2026년에는 1인 경영체 연 50만 원(작년 40만 원), 2인 이상 경영체는 1인당 연 45만 원으로 올랐습니다. 3월 9일~31일 주소지 읍·면사무소와 동 주민센터에서 신청받았습니다.', null, null, array['신청연도 1월 1일 기준 3년 이상 도내 거주', '농업경영정보 2년 이상 계속 등록하고 실제 영농에 종사', '제외: 직장보험 가입자, 2024년 농외 종합소득 3,700만 원 이상, 지방세 체납자']::text[], '{}'::text[], null, null, '제주특별자치도 발표(언론 보도), 제주특별자치도 농업기술원 보도자료', '2026-11-15', '[{"label":"뉴스서울: 제주도 2026년 농민수당·여성농업인 행복이용권 신청 안내","url":"https://newsseoul.co.kr/news/view/1065597083320393"}]'::jsonb),
  (44, 'jeju-women-farmer-voucher-2026', '여성농업인 행복이용권 (제주특별자치도, 2026)', '제주특별자치도', '{}'::text[], array['보조금']::text[], 20, 79, null, array['제주특별자치도 전체']::text[], null, null, '{}'::text[], true, '2026-03-09', '2026-03-31', '2026-03-09', '여성농업인에게 1인당 20만 원을 NH채움카드 바우처로 지원합니다. 3월 9일~31일 주소지 읍·면사무소와 동 주민센터에서 신청받았고, 작년 수급자는 자격 확인 후 기존 카드에 자동 충전됩니다.', null, null, array['도내 거주 만 20세 이상 80세 미만 여성 (1946~2005년 출생)', '농업경영체 경영주 등록', '제외: 직장보험 가입자, 지방세 체납자, 여성어업인 바우처·문화누리카드 중복 수혜자']::text[], '{}'::text[], null, null, '제주특별자치도 발표(언론 보도)', '2026-11-10', '[{"label":"뉴스서울: 제주도 2026년 농민수당·여성농업인 행복이용권 신청 안내","url":"https://newsseoul.co.kr/news/view/1065597083320393"}]'::jsonb),
  (45, 'jeju-agri-youth-farmer-school-2026', '미래농업의 주역 청년농업인 학교 교육 (농업기술원, 2026)', '제주특별자치도 농업기술원', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-04-08', '2026-04-28', '2026-04-08', '청년농업인을 위한 농업기술원 교육과정입니다. 4월 29일~6월 11일 농업기술원에서 운영했고 정원은 27명이었습니다. 접수는 4월 8일~28일 온라인 또는 방문으로 받았습니다. 교육 대상과 세부 내용은 농업기술원 영농교육 안내에서 확인하시기 바랍니다.', null, null, array['세부 대상은 영농교육 안내에서 확인 (정원 27명)', '신청: 온라인 또는 방문']::text[], '{}'::text[], 'https://agri.jeju.go.kr/agri/farminginfo/education/agri.htm', null, '제주특별자치도 농업기술원 영농교육', '2026-11-10', '[]'::jsonb),
  (46, 'jeju-agri-ict-smartfarm-edu-2026', 'ICT 활용 스마트팜 기술 습득 교육 (농업기술원, 2026)', '제주특별자치도 농업기술원 기술지원조정과 기술지원팀', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-04-28', '2026-05-12', '2026-04-28', 'ICT를 활용한 스마트팜 기술을 배우는 교육입니다. 5월 19일~6월 2일 3회 12시간 농업기술원 본원 대강당에서 운영했고 정원은 40명(온라인 신청 10명)이었습니다. 접수는 4월 28일부터 전화·방문은 5월 8일까지, 온라인은 5월 12일까지였습니다. 문의: 064-760-7533', null, null, array['스마트농업에 관심 있는 농업인 및 직원 등 40명', '선발 순위: 1순위 스마트팜 운영농가, 2순위 시설재배농가, 3순위 일반농가, 4순위 직원', '여성 10% 우선 선발, 인원 초과 시 연령이 낮은 농가 → 재배면적이 넓은 농가 순', '신청: 전화(760-7533)·방문 또는 농업기술원 누리집 온라인']::text[], '{}'::text[], 'https://agri.jeju.go.kr/agri/farminginfo/education/agri.htm', null, '제주특별자치도 농업기술원 영농교육·공지사항', '2026-11-15', '[{"label":"농업기술원 공지: 2026 ICT 활용 스마트팜 기술 습득 교육 신청 안내","url":"https://agri.jeju.go.kr/agri/notice/notice.htm?page=2&act=view&seq=61277"}]'::jsonb),
  (47, 'jeju-seobu-wheat-baking-edu-2026', '제주 우리밀 활용 제과·제빵 교육 (서부농업기술센터, 2026)', '제주특별자치도 서부농업기술센터', array['판로', '영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-09-28', '2026-10-08', '2026-09-14', '제주 우리밀(백강밀 등)을 이해하고 제과·제빵에 활용하는 실습 교육입니다. 10월 15일~29일 총 5회, 서부농업기술센터 농산물 가공교육장에서 20명 규모로 열렸습니다. 접수는 9월 28일 09:00~10월 8일 18:00였습니다. 문의: 064-760-7931~2', null, null, array['교육 대상은 과정 안내에 명시되지 않음 (정원 20명)']::text[], '{}'::text[], 'https://agri.jeju.go.kr/jadx/web/nagriedu/eduCrs.do?mode=dtlEdu&corsUid=C_20260914155625830140a&enfcInstNm=SEOBU&pageIndex=1', null, '제주특별자치도 농업기술원 영농교육', '2026-11-10', '[]'::jsonb),
  (48, 'jeju-seogwipo-rural-convergence-basic-2026', '농촌융복합 활성화 기초과정 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['판로', '영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-03-13', null, '2026-03-05', '농업을 기반으로 생산․가공․유통 및 체험관광을 연계한 농촌융복합산업을 주도할 경영체 육성 및 농업․농촌자원 활용 부가가치 향상 도모', array['교육기간: 2026. 4. 9.(목) ~ 4. 14.(화) 3회 13시간', '장 소: 서귀포농업기술센터 교육관', '교육내용: 농촌융복합과 농촌여행 트렌드, 농촌융복합 멘토링 치유프로그램 사례 실습 및 내농장 이미지 영상 홍보 마케팅 기법 등', '※ 교육일정 및 교육내용은 변경될 수 있습니다.', '교육홍보: 서귀포농업기술센터 홈페이지 및 마을 홍보', '접수기간: 2026. 3. 13.(금) 09:00 ~ 모집 인원 마감 시(선착순 접수)', '접수방법: 전화 및 방문 접수', '- 서귀포농업기술센터 농촌자원팀(☎ 760-7831~7833)', '수료(이수)증 발급 기준', '- 수료증: 전체 교육 기간(또는 시간) 80% 이상 출석 한 경우', '- 이수증: 전체 교육 기간(또는 시간) 30% 이상 80% 미만 출석 한 경우', '※ 접수 후 수강하지 않는 경우 농촌자원 활용 교육 신청 제한']::text[], null, array['대상 및 인원: 관내 농촌융복합사업자 및 교육희망자 50명']::text[], '{}'::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=2&act=view&seq=59512', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (49, 'jeju-seogwipo-new-farmer-field-practice-2026', '신규농업인 현장실습교육 (서귀포농업기술센터, 2026)', '제주특별자치도 서귀포농업기술센터', array['영농기술']::text[], array['교육']::text[], null, null, null, '{}'::text[], null, null, array['신규농']::text[], null, '2026-02-09', '2026-02-13', '2026-02-04', '농촌지역에 이주한 신규농업인 및 청년농업인 등에게 영농기술 및 품질관리, 경영‧마케팅, 창업 등에 필요한 단계별 실습교육을 통하여 안정적인 영농 연착륙이 가능하도록 유도함으로써 농촌의 활력 증진', array['사업기간: 2026년 3월 ~ 11월 (기간 중 5개월)', '사 업 량: 2개팀 4명(연수생 2명, 선도농가 2명)', '사 업 비: 12,000천원(국비 6,000 도비 6,000)', '사업내용: 작목 중심, 선도 농가 협력 현장실습 지원 등', '【 연수생 】 (지원금액) 월 80만원 기준(3∼7개월간) 지급', '【 선도농가 】 (지원금액) 월 40만원 기준(3∼7개월) 지급', '신청기간: 2026. 2. 9.(월) ~ 2. 13.(금) 18:00까지', '신청방법 및 장소: 방문접수 (서귀포농업기술센터 농촌자원팀)', '중대한 허위사실로 약정체결하여 약정 무효된 자 또는 허위연수 적발 등으로 약정 취소된 자는 추후 사업대상에서 영구제외', '신규농업인 현장실습교육 대상자(연수생 및 선도농가) 선발 또는 실습 교육 시작 후 특별한 사유 없이 교육 참여를 포기하는 연수생 또는 선도농가는 다음 연도부터 3년간 당해 사업대상에서 제외']::text[], null, array['【 연수생 】※ 5가지 조건 중 1가지 조건이라도 해당되면 대상자', '농식품부 2026년도「청년농업인 영농정착지원사업」신청자', '농촌 이주 5년 이내 귀농인', '* 최초 공고 인원 미달 시 농촌 이주 7년 이내 귀농인으로 확대 가능', '농업경영체 등록 5년 이내 신규농업인', '만 40세 미만 청장년층 (귀농 여부 및 지역과 상관없이 지원 가능)', '* 최초 공고 인원 미달 시 만 49세 미만으로 확대 가능', '예비귀농인(공인된 기관에서 실시한 귀농교육을 35시간 이상 이수하고 농어촌지역으로 이주계획이 구체적으로 확인되는 경우)', '【 선도 농가 】※ 아래 자격조건 중 1가지 이상 해당하면 신청 가능', '관내 신지식농업인, 전문농 및 창업농업경영인, ICT(정보통신기술) 활용 농가, 우수농업법인, 농식품부 지정 현장실습교육장(WPL), 농업 명인, 농업마이스터 등으로 다음의 요건을 충족한 농업경영체', '①지역에서 신망이 있고, 교육자적 소양을 갖춘 농업경영체(선정 시 농촌진흥사업 시범 교육장 운영 또는 농촌진흥기관의 교육수료자를 우대 가능)', '②5년 이상의 영농경력과 전문적 기술을 갖춘 농업경영체(단, 연수생이 초보단계의 귀농인인 경우 3년 이상 경력의 정착 귀농인도 선도농가로 선정 가능)']::text[], array['【연수생】 ① 신규농업인 현장실습교육장 연수신청서(붙임 3)', '【연수생】 * e-HRD 시스템에 연수생용 현장실습교육 추진계획서(붙임 4) 입력', '【연수생】 ② 보안서약서(붙임 9) 및 개인정보 이용동의서(붙임 10)', '【연수생】 ③ 주민등록등본 및 가족관계증명서', '【연수생】 ④ 귀농교육수료증(온ㆍ오프라인)', '【연수생】 ⑤ 농업경영체등록확인서 및 농지대장', '【선도농가】 ① 신규농업인 현장실습교육장 지정신청서(붙임 5)', '【선도농가】 ② 신규농업인 현장실습교육장 운영계획서(붙임 6)', '【선도농가】 ③ 보안서약서(붙임 9) 및 개인정보 이용동의서(붙임 10)']::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=2&act=view&seq=59384', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb),
  (50, 'jeju-4h-award-45th-2026', '제45회 제주특별자치도 4-H대상 후보자 추천', '제주특별자치도 서귀포농업기술센터', array['네트워크(지역사회 관계)']::text[], '{}'::text[], null, null, null, '{}'::text[], null, null, '{}'::text[], null, '2026-06-19', '2026-07-03', '2026-06-11', '지·덕·노·체의 4-H 이념을 실천하는 모범 4-H회와 회원, 지도자를 발굴해 시상하는 제45회 제주특별자치도 4-H대상 후보자 추천 공고입니다. 2026년 6월 19일~7월 3일(15일간) 농업기술센터소장 추천으로 제주특별자치도4-H본부에서 방문·이메일·우편으로 접수했습니다. 시상은 2026년 10월 초 농어업인회관 대강당에서 열릴 예정이었습니다. 문의: 064-749-4440', null, null, array['4-H봉사: 농업기술센터에 등록해 3년 이상 활동한 4-H회원', '모범4-H회: 농업기술센터에 등록해 5년 이상 활동한 4-H회 (학교·본부)', '모범4-H회원: 3년 이상 활동한 청년 회원, 학교4-H회 1년 이상 활동한 학생 회원', '모범4-H지도자: 경력 3년 이상 지도교사·지도자', '추천기관: 농업기술센터소장']::text[], array['4-H대상 추천서 및 공적요약서', '공적조서', '현지조사확인서', '이력서 (개인 부문은 증명사진)', '포상에 대한 개인정보 제공 동의서', '대표 활동사진 15장 (이메일 제출)', '심사에 필요한 증빙자료', '부문별 추가 서류 (과제기록장 사본, 연간활동계획서, 회칙 등)']::text[], 'https://agri.jeju.go.kr/seogwipo/notice/notice.htm?page=1&act=view&seq=61494', null, '서귀포농업기술센터 공지사항', '2026-11-15', '[]'::jsonb);
